begin;
create function pg_temp.ok(p boolean,msg text) returns void language plpgsql as $$begin if p is distinct from true then raise exception 'ASSERT: %',msg;end if;end $$;
create function pg_temp.reject(q text,code text) returns void language plpgsql as $$begin begin execute q; exception when others then if sqlstate=code then return;end if;raise;end;raise exception 'EXPECTED REJECTION: %',code;end $$;
insert into auth.users(id,email) values('a2210000-0000-4000-8000-000000000001','owner@test.invalid'),('a2210000-0000-4000-8000-000000000002','worker@test.invalid'),('a2210000-0000-4000-8000-000000000003','other@test.invalid');
insert into public.tenants(id,name,slug,timezone,currency) values('a2210000-0000-4000-8000-000000000010','A','roster-test-a','UTC','USD'),('b2210000-0000-4000-8000-000000000010','B','roster-test-b','UTC','USD');
insert into public.tenant_members(tenant_id,user_id,role) values('a2210000-0000-4000-8000-000000000010','a2210000-0000-4000-8000-000000000001','BUSINESS_OWNER');
insert into public.services(id,tenant_id,name,archetype,currency,base_price) values('a2210000-0000-4000-8000-000000000020','a2210000-0000-4000-8000-000000000010','A','simple','USD',0),('b2210000-0000-4000-8000-000000000020','b2210000-0000-4000-8000-000000000010','B','simple','USD',0);
select pg_temp.ok(public.roster_provision('a2210000-0000-4000-8000-000000000001','a2210000-0000-4000-8000-000000000010')=1,'provision');
create function pg_temp.v() returns bigint language sql as $$select version from public.worker_roster_state where tenant_id='a2210000-0000-4000-8000-000000000010'$$;
create function pg_temp.worker(id uuid,n text,active boolean,creation boolean) returns bigint language sql as $$select public.roster_worker_put('a2210000-0000-4000-8000-000000000001','a2210000-0000-4000-8000-000000000010',pg_temp.v(),id,n,active,creation)$$;
select pg_temp.ok(pg_temp.worker('a2210000-0000-4000-8000-000000000030','A worker',true,true)=2,'worker create increments');
select pg_temp.ok(pg_temp.worker('a2210000-0000-4000-8000-000000000031','Other worker',true,true)=3,'worker2');
select pg_temp.reject($q$select pg_temp.worker('a2210000-0000-4000-8000-000000000030','Wrong create',true,true)$q$,'40001');
select pg_temp.ok(pg_temp.v()=3,'failed create rolls version back');
select pg_temp.reject($q$select pg_temp.worker('a2210000-0000-4000-8000-000000000030','Name'||repeat(' ',161),true,false)$q$,'23514');
select pg_temp.reject($q$select public.roster_worker_put('a2210000-0000-4000-8000-000000000001','a2210000-0000-4000-8000-000000000010',2,'a2210000-0000-4000-8000-000000000030','stale',true,false)$q$,'40001');
select pg_temp.worker('a2210000-0000-4000-8000-000000000030','Renamed',false,false);
select pg_temp.ok((select not active from public.workers where id='a2210000-0000-4000-8000-000000000030'),'deactivate retained');
create function pg_temp.access(u uuid,w uuid,active boolean,creation boolean) returns bigint language sql as $$select public.roster_access_put('a2210000-0000-4000-8000-000000000001','a2210000-0000-4000-8000-000000000010',pg_temp.v(),u,w,active,creation)$$;
select pg_temp.access('a2210000-0000-4000-8000-000000000002','a2210000-0000-4000-8000-000000000030',true,true);
select pg_temp.reject($q$select pg_temp.access('a2210000-0000-4000-8000-000000000003','a2210000-0000-4000-8000-000000000030',true,true)$q$,'23505');
select pg_temp.reject($q$select pg_temp.access('a2210000-0000-4000-8000-000000000002','a2210000-0000-4000-8000-000000000031',true,false)$q$,'55000');
select pg_temp.access('a2210000-0000-4000-8000-000000000002','a2210000-0000-4000-8000-000000000030',false,false);
select pg_temp.ok((select not active and revoked_at is not null and permission_version=2 from public.worker_access),'revoke fence');
select pg_temp.access('a2210000-0000-4000-8000-000000000002','a2210000-0000-4000-8000-000000000030',true,false);
select pg_temp.ok((select active and revoked_at is null and permission_version=3 from public.worker_access),'reactivation version');
select pg_temp.ok(not exists(select 1 from public.tenant_members where user_id='a2210000-0000-4000-8000-000000000002'),'no worker tenant role');
select public.roster_crew_put('a2210000-0000-4000-8000-000000000001','a2210000-0000-4000-8000-000000000010',pg_temp.v(),'a2210000-0000-4000-8000-000000000040','Crew',true,true);
select public.roster_crew_member_set('a2210000-0000-4000-8000-000000000001','a2210000-0000-4000-8000-000000000010',pg_temp.v(),'a2210000-0000-4000-8000-000000000040','a2210000-0000-4000-8000-000000000030',true);
select pg_temp.reject($q$insert into public.crew_members values('b2210000-0000-4000-8000-000000000010','a2210000-0000-4000-8000-000000000040','a2210000-0000-4000-8000-000000000030')$q$,'23503');
select public.roster_eligibility_put('a2210000-0000-4000-8000-000000000001','a2210000-0000-4000-8000-000000000010',pg_temp.v(),'a2210000-0000-4000-8000-000000000020','a2210000-0000-4000-8000-000000000030',true,true);
select pg_temp.reject($q$select public.roster_eligibility_put('a2210000-0000-4000-8000-000000000001','a2210000-0000-4000-8000-000000000010',pg_temp.v(),'b2210000-0000-4000-8000-000000000020','a2210000-0000-4000-8000-000000000030',true,true)$q$,'23503');
select pg_temp.reject($q$delete from public.services where id='a2210000-0000-4000-8000-000000000020'$q$,'23503');
create function pg_temp.shift(zone text,e timestamptz) returns bigint language sql as $$select public.roster_shift_put('a2210000-0000-4000-8000-000000000001','a2210000-0000-4000-8000-000000000010',pg_temp.v(),'a2210000-0000-4000-8000-000000000050','a2210000-0000-4000-8000-000000000030','available','2030-01-01T10:00Z',e,zone,true,true)$$;
select pg_temp.reject($q$select pg_temp.shift('Made/Up','2030-01-01T11:00Z')$q$,'22023');
select pg_temp.reject($q$select pg_temp.shift('UTC','2030-01-01T09:00Z')$q$,'23514');
select pg_temp.reject($q$select pg_temp.shift('UTC','infinity')$q$,'23514');
select pg_temp.shift('America/New_York','2030-01-01T11:00Z');
select pg_temp.reject($q$update public.worker_shifts set worker_id='a2210000-0000-4000-8000-000000000031'$q$,'55000');
select pg_temp.reject($q$update public.worker_access set worker_id='a2210000-0000-4000-8000-000000000031'$q$,'55000');
select pg_temp.reject($q$select public.roster_provision('a2210000-0000-4000-8000-000000000002','a2210000-0000-4000-8000-000000000010')$q$,'42501');
update public.tenants set status='suspended' where id='a2210000-0000-4000-8000-000000000010';
select pg_temp.reject($q$select pg_temp.worker('a2210000-0000-4000-8000-000000000030','Forbidden',true,false)$q$,'42501');
update public.tenants set status='active' where id='a2210000-0000-4000-8000-000000000010';
update public.worker_access set permission_version=9007199254740991;
select pg_temp.reject($q$select pg_temp.access('a2210000-0000-4000-8000-000000000002','a2210000-0000-4000-8000-000000000030',false,false)$q$,'22023');
update public.worker_roster_state set version=9007199254740991;
select pg_temp.reject($q$select pg_temp.worker('a2210000-0000-4000-8000-000000000030','Overflow',true,false)$q$,'22023');
select pg_temp.ok((select count(*)=7 and bool_and(relrowsecurity and relforcerowsecurity) from pg_class where relnamespace='public'::regnamespace and relname in('worker_roster_state','workers','worker_access','crews','crew_members','service_worker_eligibility','worker_shifts')),'all RLS forced');
select pg_temp.ok(not exists(select 1 from pg_class t cross join (values('anon'),('authenticated'),('service_role')) r(role) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) p(priv) where t.relnamespace='public'::regnamespace and t.relname in('worker_roster_state','workers','worker_access','crews','crew_members','service_worker_eligibility','worker_shifts') and has_table_privilege(r.role,t.oid,p.priv)),'147 raw grants denied');
select pg_temp.ok(not exists(select 1 from pg_proc p cross join (values('anon'),('authenticated')) r(role) where p.pronamespace='public'::regnamespace and p.proname like 'roster_%' and has_function_privilege(r.role,p.oid,'EXECUTE')),'RPC not public');
rollback;
\echo WORKER ROSTER TESTS PASS
